import sys
import logging
from functools import partial
import multiprocessing as mp
import warnings

from taf.analyzer.base import LogReader
from .ttitrace_event import TtitraceEvent
from .initializer import initialize, create_decoder, get_decoder_size

SW_EVENT_HEADER_SIZE = 8

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TtitraceReader(LogReader):
    """
    Read a file with UDP binary data for TTI events in streaming mode-

    Usage:

    * Read a file with UDP binary data for TTI events in streaming mode and handle each event

            Code::

                file_name = '/tmp/ttitrace_streaming.udp'
                multi_base_folder = '/tmp/generated_tti_trace'

                with open(file_name, 'rb') as file_obj:
                    for event in TtitraceReader(
                            multi_base_folder=multi_base_folder,
                            file_obj=file_obj):
                        # handle event
    """

    def __init__(self, multi_base_folder='/opt/tti_dissectors', **kwargs):
        """
        Create a TTI trace event reader.

        :param str multi_base_folder:         path to the MuLTI python classes installation folder
        :param int sw_event_size (deprecated\: tti_trace_message_size):
            overrides SW event size gotten from StreamComponentInd_t
        """  # noqa: W605
        warnings.warn('This library is deprecated, use "taf.analyzer.ttitrace_eventdecoder" instead.',
                      FutureWarning,
                      stacklevel=2)
        sw_event_size = kwargs.pop("sw_event_size", None) or kwargs.pop("tti_trace_message_size", None)
        super(TtitraceReader, self).__init__(**kwargs)
        initialize(multi_base_folder)
        if sys.version_info[0] >= 3:
            mp_spawn = mp.get_context('spawn')
            self.worker_pool = mp_spawn.Pool(
                processes=mp.cpu_count(),
                initializer=initialize,
                initargs=(multi_base_folder,))
        if sw_event_size is None:
            sw_event_payload_size = get_decoder_size()
            self._sw_event_size = sw_event_payload_size + SW_EVENT_HEADER_SIZE
        else:
            self._sw_event_size = sw_event_size

    def _get_worker_argument_list(self, message_chunk):
        """
        Create an argument list for the _decode_message method.

        This is required due to the usage of multiprocessing pool.

        :return: list of ttitrace messages, list length equals to number of cpus
        """
        return_list = []
        for i in range(0, len(message_chunk) // self._sw_event_size):
            offset = self._sw_event_size * i
            sw_event_payload = message_chunk[SW_EVENT_HEADER_SIZE + offset:self._sw_event_size + offset]
            return_list.append(sw_event_payload)
        return return_list

    def __iter__(self):  # noqa: C901
        """
        Yield next decoded TTI event.
        """
        decoded_message_list = []
        if sys.version_info[0] < 3:
            parallel_worker = 1
        else:
            parallel_worker = mp.cpu_count()
        for sw_events in iter(partial(self._file_obj.read, self._sw_event_size * (parallel_worker)), b""):
            try:
                if parallel_worker == 1:
                    sw_event_payload = sw_events[SW_EVENT_HEADER_SIZE:len(sw_events)]
                    decoded_message_list = [decode_message(sw_event_payload)]
                else:
                    decoded_message_list = self.worker_pool.map(
                        decode_message,
                        self._get_worker_argument_list(sw_events))
            except Exception as e:
                logger.warning(repr(e))
            for decoded_message in decoded_message_list:
                if decoded_message is not None and "AssertionError" not in decoded_message:
                    for event in decoded_message['tracePayload']['events']:
                        yield TtitraceEvent(event)
                else:
                    logger.warning(decoded_message)


def decode_message(sw_event_payload):
    """
    Decodes the binary UDP data of a StreamComponentInd message.

    :param  ttitrace_message:    binary data representing a tti message
    :return: decoded StreamComponentInd message
    """
    if sw_event_payload is None:
        return None
    decoded_message = create_decoder().decode(sw_event_payload)
    if isinstance(decoded_message, AssertionError):
        return repr(decoded_message)
    else:
        return decoded_message
